package main

import (
	"gno.land/r/gnops/valopers/proposal"
	"gno.land/r/gov/dao"
)

// Create the GovDAO proposal "Add valoper Mithrandir to the valset" from the
// on-chain valoper profile (power 1 for a newcomer) and cast this member's YES.
// Execution waits for a second member's vote: dao.ExecuteProposal(pid) later.
func main(cur realm) {
	r := proposal.NewValidatorProposalRequest(cross(cur), address("g1ecsuj0q572jr0dhu29q9njtnmw03hyu7tyyvv6"))
	pid := dao.MustCreateProposal(cross(cur), r)
	dao.MustVoteOnProposal(cross(cur), dao.NewVoteRequest(dao.YesVote, pid))
	println("proposal", pid)
}
